const STY = (bg, w, h, f) => `position:absolute;width:${w}px;height:${h}px;left:${(940-w)/2}px;display:flex;align-items:center;justify-content:center;text-align:center;border-radius:46px;background:linear-gradient(180deg,color-mix(in srgb,${bg} 72%,#fff),${bg} 55%,color-mix(in srgb,${bg} 84%,#000));box-shadow:0 26px 40px -14px rgba(0,0,0,.5),inset 0 4px 0 rgba(255,255,255,.5);color:#0b1020;font-family:inherit;font-weight:800;font-size:${f}px;line-height:1.1;opacity:0;`;
const B1 = 'var(--acc)', B2 = 'var(--acc2)';

root.innerHTML = `
  <div id="c0" style="${STY(B1, 820, 160, 62)}top:80px;">CLAUDE CODE<br>TRADING SKILLS</div>
  <div id="st" style="position:absolute;top:280px;width:100%;text-align:center;color:#ffffff;font-size:90px;font-weight:900;opacity:0;letter-spacing:-3px;">4,170 STARS</div>
  <div id="f1" style="${STY(B2, 740, 110, 44)}top:410px;">MARKET ANALYSIS</div>
  <div id="f2" style="${STY(B1, 740, 110, 44)}top:540px;">TECHNICAL CHARTING</div>
  <div id="f3" style="${STY(B2, 740, 110, 44)}top:670px;">TRADING STRATEGIES</div>
  <div id="ft" style="${STY(B1, 820, 120, 48)}top:840px;">PYTHON • MIT LICENSE<br>FREE TO MODIFY</div>
`;

const main = root.querySelector('#c0');
const star = root.querySelector('#st');
const feats = [root.querySelector('#f1'), root.querySelector('#f2'), root.querySelector('#f3')];
const foot = root.querySelector('#ft');

function frame(t, p, d) {
  // Title pop
  const s0 = spr(t, 0.1, 0.8, 10);
  main.style.opacity = s0;
  main.style.transform = `scale(${lerp(0.8, 1, s0)}) translateY(${lerp(40, 0, s0)}px)`;

  // Stars count/reveal
  const s1 = spr(t, 0.6, 0.8, 10);
  star.style.opacity = s1;
  star.style.transform = `scale(${lerp(0.5, 1, s1)})`;
  const count = Math.floor(lerp(0, 4170, E_OUT(clamp((t - 0.5) * 1.5))));
  star.textContent = count.toLocaleString() + ' STARS';

  // Features sliding from behind title
  feats.forEach((f, i) => {
    const sF = spr(t, 1.2 + i * 0.15, 0.85, 10);
    const startY = 80 - (410 + i * 130); // Offset to start at main card position
    f.style.opacity = sF;
    f.style.transform = `translateY(${lerp(startY, 0, sF)}px)`;
  });

  // Footer rise
  const sEnd = spr(t, 2.2, 0.8, 8);
  foot.style.opacity = sEnd;
  foot.style.transform = `translateY(${lerp(50, 0, sEnd)}px)`;

  // Subtle drift to keep visual alive but settled
  const drift = lerp(0, 15, E_OUT(p));
  root.style.transform = `translateY(${-drift}px)`;
}
